<script setup lang="ts">
import Icon from './Icon.vue'
defineProps<{task:{task_id:string,app_task_id?:string,app_id:string,status:string,can_retry:boolean,progress:{percent?:number}},position?:number,labels:Record<string,string>,t:(value:string)=>string}>()
defineEmits(['detail','cancel','retry','delete'])
const stopped=['succeeded','failed','cancelled']
</script>
<template><div class="schedule-card" :class="task.status"><div class="card-heading"><span v-if="position" class="queue-position">{{position}}</span><button class="task-link" @click="$emit('detail')">{{task.app_task_id||task.task_id.slice(0,8)}}</button><span class="status" :class="task.status">{{labels[task.status]||task.status}}</span></div><small>{{task.app_id}}</small><div v-if="task.status==='running'" class="card-progress"><div class="meter"><div :style="{width:`${(task.progress.percent||0)*100}%`}"></div></div><span>{{Math.round((task.progress.percent||0)*100)}}%</span></div><div class="card-actions"><button v-if="['queued','retry_wait','assigned','running','recovering'].includes(task.status)" class="text-button" @click="$emit('cancel')"><Icon name="close"/>{{t('取消')}}</button><button v-if="task.can_retry" class="text-button" @click="$emit('retry')"><Icon name="refresh"/>{{t('重试')}}</button><button class="text-button subdued" :disabled="!stopped.includes(task.status)" :title="!stopped.includes(task.status)?t('确认停止后可删除'):t('删除')" @click="$emit('delete')"><Icon name="trash"/>{{t('删除')}}</button><button class="text-button" @click="$emit('detail')">{{t('任务详情')}}<Icon name="arrow"/></button></div></div></template>
